<template>
  <ion-page><ion-content><div class="service-mobile rotation-mobile">
    <header><button @click="$router.push(canPunch?'/app/attendance':'/app/tabs/home')">返回</button><h1>{{canPunch?'我的排班与待休':'现场轮休审批'}}</h1><p>个人排班和休息额度跨现场轮休项目累计；每满 6 个有效工作日获得 1 天额度。</p></header>
    <p v-if="error" role="alert" class="service-error">{{error}}</p>
