      <label class="service-field">参与人员<select v-model.number="personPlan.employee_id" @change="personChanged"><option :value="0" disabled>选择一人</option><option v-for="member in schedulableMembers" :key="member.id" :value="member.id">{{member.name}}</option></select></label>
