      <label class="service-field">开始日期<input v-model="personPlan.start_date" type="date" @change="personStartChanged"/></label>
      <label class="service-field">结束日期<input v-model="personPlan.end_date" type="date" @change="personRangeChanged"/></label>
      <label class="service-field">周期起点<input v-model="personPlan.cycle_start" type="date" @change="personRangeChanged"/></label>
      <p class="muted">至少覆盖一个完整周期；可延长并重复模板。换项目时个人周期不重置。</p>
      <label class="service-field">原因<textarea v-model="personPlan.reason" maxlength="500" @input="invalidatePersonPreview"></textarea></label>
      <button class="service-primary" :disabled="saving || !canPreviewPerson" @click="previewPerson">预览此人排班</button>
      <button class="service-primary" :disabled="saving || !canConfirmPerson" @click="confirmPerson">{{rotationRule?'确认并发布此人排班':'确认此人待生效排班'}}</button>
      <div v-if="savedPersonPlans.length" class="saved-plans"><p>此人已确认的周期</p><button v-for="saved in savedPersonPlans" :key="saved.id" @click="editSavedPlan(saved)">{{saved.start_date}} — {{saved.end_date}} · {{templateLabel(saved.template)}}</button><button @click="newPersonPlan">新建下一段</button></div>
      <div v-if="bindableDays.length" class="saved-plans"><p>可接入本项目的待分配日期</p><label v-for="day in bindableDays" :key="`${day.plan_id}-${day.date}`"><input v-model="selectedBindableDates" type="checkbox" :value="`${day.plan_id}|${day.date}`"/>{{day.date}} · {{labels[day.kind]}}</label><button :disabled="saving || !selectedBindableDates.length" @click="bindSelectedDays">确认接入本项目</button></div>
      <div v-if="personRows.length" class="plan-preview"><div v-for="row in personRows" :key="row.date" class="plan-row"><span>{{row.date}}<br/><small>{{personStatusLabel(row.status || 'preview')}}</small></span><div><select :value="row.kind" :aria-label="`${row.date} 安排`" @change="editPersonDay(row.date,'kind',($event.target as HTMLSelectElement).value)"><option value="work">上班</option><option value="rest">休息</option></select><select :value="row.project_id == null ? 'pending' : String(row.project_id)" :aria-label="`${row.date} 项目`" @change="editPersonDay(row.date,'project_id',($event.target as HTMLSelectElement).value)"><option :value="String(projectId)">{{projectName(projectId)}}</option><option value="pending">待分配项目</option></select><select :value="row.shift_label || ''" :disabled="row.kind!=='work'" :aria-label="`${row.date} 班别`" @change="editPersonDay(row.date,'shift_label',($event.target as HTMLSelectElement).value)"><option value="">未指定</option><option value="day">白班</option><option value="night">夜班</option></select></div></div></div>
      <p v-if="personRows.length" class="muted">修改每天的安排后请重新预览并确认。待分配项目日期保留周期，但不能打卡。</p>
    </section>
    <section v-if="manageView && adjustRow" class="service-card review"><h2>申请调整已发布排班</h2><p>{{adjustRow.employee_name}} · {{adjustRow.date}} · {{projectName(adjustRow.project_id)}}</p><label class="service-field">调整为<select v-model="adjustKind"><option value="work">上班</option><option value="rest">正常轮休</option></select></label><label v-if="adjustKind==='work'" class="service-field">班别（仅展示）<select v-model="adjustShiftLabel"><option value="">保留原班别</option><option value="none">不标注班别</option><option value="day">白班</option><option value="night">夜班</option></select></label><label class="service-field">原因<textarea v-model="adjustReason" maxlength="500" placeholder="填写调班原因"></textarea></label><p class="muted">提交后由项目组长、区域组长、售后经理依次审核，全部通过后生效。</p><button class="service-primary" :disabled="saving || !adjustReason.trim()" @click="submitAdjustment">提交调班申请</button><button @click="adjustRow=null">返回</button></section>
    <section v-if="canPunch" class="service-card"><h2>提交申请</h2><label class="service-field">申请项目<select v-model.number="form.project_id"><option :value="0" disabled>选择项目</option><option v-for="p in directory.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label>
      <label class="service-field">申请类型<select v-model="form.kind" @change="form.dayKind=form.kind==='leave'?'leave':'work'"><option value="schedule">调班 / 休息日出勤安排</option><option value="credit">休息日出勤事后确认</option><option value="leave">使用待休余额</option></select></label>
      <label class="service-field">开始日期<input v-model="form.start" type="date"/></label><label class="service-field">结束日期<input v-model="form.end" type="date"/></label>
      <label class="service-field">安排<select v-model="form.dayKind"><template v-if="form.kind==='leave'"><option value="leave">全天调休</option><option value="half_leave">半天调休</option></template><template v-else><option value="work">上班 / 出勤</option><option v-if="form.kind==='schedule'" value="rest">正常轮休</option></template></select></label>
      <label v-if="form.kind==='schedule' && form.dayKind==='work'" class="service-field">班别（仅展示）<select v-model="form.shiftLabel"><option value="">未指定</option><option value="day">白班</option><option value="night">夜班</option></select></label>
      <label class="service-field">原因<textarea v-model="form.reason" maxlength="500" placeholder="说明现场安排或事后确认原因"></textarea></label><button class="service-primary" :disabled="saving||!form.project_id" @click="submit">{{form.kind==='schedule'?'提交逐级审核':'提交售后经理审批'}}</button>
    </section>
    <section class="service-card"><h2>{{manageView?'项目申请与审批':'我的申请'}}</h2><article v-for="c in data.claims" :key="c.id" class="claim"><strong>{{c.employee_name}} · {{claimLabels[c.kind]}} · {{statusLabels[c.status]||c.status}}</strong><p>{{c.days.map((d:any)=>`${d.date}${d.shift_label?` · ${shiftLabel(d.shift_label)}`:''}`).join('、')}}</p><p v-if="c.status==='pending'&&c.next_approval">待{{approvalRoleLabel(c.next_approval.role)}}审批</p><p v-if="c.approval_steps?.length" class="muted">{{c.approval_steps.map((s:any)=>`${approvalRoleLabel(s.role)}：${stepStatusLabel(s.status)}`).join(' → ')}}</p><p>{{c.reason}}</p><p v-if="c.current_facts">实际{{Number(c.current_facts.hours).toFixed(2)}} / {{c.current_facts.required_hours}}小时，建议{{c.current_facts.suggested_days}}天</p><p v-if="c.needs_review" class="service-error">打卡已变化，原确认额度需复核。</p><p v-if="c.review_note">审核：{{c.review_note}} · {{c.days_amount}}天</p><div v-if="manageView&&c.can_review"><button v-if="c.status==='pending'" @click="openReview(c,'approve')">批准</button> <button v-if="c.status==='pending'" @click="openReview(c,'reject')">驳回</button><button v-if="c.status==='approved'" @click="openReview(c,'revoke')">撤销</button></div></article><p v-if="!data.claims.length" class="muted">暂无申请</p></section>
    <section v-if="canPunch" class="service-card"><h2>我的额度流水</h2><p v-for="item in entitlement.ledger" :key="item.id">{{ item.date }} · {{ ledgerActionLabel(item.action) }}<template v-if="item.delta_days"> · 可用额度 {{ item.delta_days > 0 ? '+' : '' }}{{ item.delta_days }} 天</template><template v-else> · 本次可用额度未变化</template><br/><small>累计进度 {{ item.progress_days == null ? '旧记录未记录' : `${item.progress_days} / 6 天` }} · 可用 {{ item.balance_days }} 天<span v-if="item.reason"> · {{ item.reason }}</span></small></p><p v-if="!entitlement.ledger.length" class="muted">暂无额度变动</p></section>
    <section v-if="manageView" class="service-card"><h2>项目待休流水</h2><p v-for="l in data.ledger" :key="l.id">申请{{l.claim_id}}：{{l.delta_units>0?'+':''}}{{l.delta_units/2}}天，余额{{l.balance_units/2}}天<br/><small>{{l.reason}}</small></p></section>
    <section v-if="reviewRow" class="service-card review"><h2>处理申请</h2><label v-if="reviewRow.kind==='credit'&&reviewAction==='approve'" class="service-field">确认天数<select v-model.number="reviewDays"><option :value="0">0天</option><option :value="0.5">0.5天</option><option :value="1">1天</option></select></label><label class="service-field">审核原因<textarea v-model="reviewNote" maxlength="500"></textarea></label><button class="service-primary" :disabled="saving" @click="review">确认{{reviewAction==='approve'?'批准':reviewAction==='reject'?'驳回':'撤销'}}</button><button @click="reviewRow=null">返回</button></section>
  </div></ion-content></ion-page>
</template>
<script setup lang="ts">
import {ref,computed} from 'vue'
import {IonPage,IonContent,onIonViewWillEnter,alertController} from '@ionic/vue'
import {get,post,put} from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
import {useRoute} from 'vue-router'
const auth=useAuthStore(),directory=ref<any>({projects:[],managed_project_ids:[],can_manage:false}),data=ref<any>({days:[],draft_days:[],claims:[],balances:[],ledger:[]}),weekData=ref<any>({days:[],draft_days:[]}),error=ref(''),saving=ref(false)
const entitlement=ref<any>({available_days:0,progress_days:0,threshold_days:6,pending_confirmation:[],planned_rest:[],ledger:[],active:false,updated_at:null})
const entitlementLoaded=ref(false),entitlementError=ref('')
const route=useRoute()
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),month=ref(today.slice(0,7)),projectId=ref(0),manageView=ref(false)
const canPunch=computed(()=>!auth.roles.includes('regional_lead')&&!auth.roles.includes('aftersales_manager'))
const canManage=computed(()=>projectId.value>0&&(directory.value.projects.find((p:any)=>p.id===projectId.value)?.can_schedule??(directory.value.can_manage||directory.value.schedule_project_ids?.includes(projectId.value))))
const canViewProjectClaims=computed(()=>auth.roles.includes('aftersales_manager')||auth.roles.includes('regional_lead')||auth.roles.includes('admin')||canManage.value)
function canScheduleProject(id:number){return !!(directory.value.projects.find((p:any)=>p.id===id)?.can_schedule??(directory.value.can_manage||directory.value.schedule_project_ids?.includes(id)))}
const selectedRule=computed(()=>directory.value.rules?.find((r:any)=>r.id===directory.value.projects.find((p:any)=>p.id===projectId.value)?.rule_id))
const rotationRule=computed(()=>selectedRule.value?.rule_type==='rotation')
const rotationProject=computed(()=>directory.value.projects?.find((p:any)=>p.id===projectId.value))
const schedulableMembers=computed<any[]>(()=>{const ids=new Set<number>();for(const item of directory.value.assignments||[])if(item.project_id===projectId.value && (item.is_current||item.status==='active'))ids.add(Number(item.employee_id));for(const item of directory.value.pending_members||[])if(item.project_id===projectId.value)ids.add(Number(item.employee_id));return (directory.value.people||[]).filter((p:any)=>ids.has(Number(p.id)))})
const labels:any={work:'上班',rest:'轮休',leave:'调休',half_leave:'半天调休',pending:'待确认'},claimLabels:any={schedule:'调班',credit:'出勤确认',leave:'调休'},statusLabels:any={pending:'待审批',approved:'已批准',rejected:'已驳回',revoked:'已撤销'}
function shiftLabel(value:string){return value==='day'?'白班':value==='night'?'夜班':''}
function projectName(id:number|null){return id == null ? '待分配项目' : directory.value.projects.find((p:any)=>p.id===id)?.name || '项目'+id}
function restStatusLabel(status:string){return ({ready:'额度已具备',pending_credit:'待兑现',pending_application:'待申请调休',pending_review:'待售后经理审批',approved:'已批准',needs_action:'待处理',pending_rule:'待规则生效',pending_project:'待分配项目'} as Record<string,string>)[status] || status}
function restNeedsAction(status:string){return ['pending_credit','pending_application','pending_review','needs_action'].includes(status)}
function ledgerActionLabel(action:string){return ({work_credit:'有效出勤入账',work_correction:'出勤更正',ordinary_rest:'常规轮休使用',ordinary_reversal:'常规轮休撤销',credit:'历史攒休入账',leave:'历史调休使用',reversal:'历史记录撤销'} as Record<string,string>)[action] || '额度调整'}
function personStatusLabel(status:string){return ({pending_rule:'待规则生效',pending_project:'待分配项目',published:'已发布',preview:'待预览'} as Record<string,string>)[status]||status}
function templateLabel(template:string){return ({six_one:'上 6 休 1',twelve_two:'上 12 休 2',eighteen_three:'上 18 休 3',custom:'自定义'} as Record<string,string>)[template]||template}
function approvalRoleLabel(role:string){return ({project_leader:'项目组长',regional_lead:'区域组长',aftersales_manager:'售后经理',admin:'系统管理员'} as Record<string,string>)[role]||role}
function stepStatusLabel(status:string){return ({pending:'待处理',approved:'已通过',rejected:'已驳回',skipped:'已跳过'} as Record<string,string>)[status]||status}
function addDays(day:string,n:number){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function monday(day:string){return addDays(day,-((new Date(day+'T12:00:00Z').getUTCDay()+6)%7))}
function dayDifference(startDay:string,endDay:string){return Math.round((new Date(endDay+'T12:00:00Z').getTime()-new Date(startDay+'T12:00:00Z').getTime())/86400000)}
function patternLength(template:string){return template==='twelve_two'?14:template==='eighteen_three'?21:7}
const weekStart=ref(monday(today)),weekEnd=computed(()=>addDays(weekStart.value,6))
const start=computed(()=>month.value+'-01'),end=computed(()=>{const d=new Date(start.value+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);return d.toISOString().slice(0,10)})
const monthOffset=computed(()=>(new Date(start.value+'T12:00:00Z').getUTCDay()+6)%7)
const calendarDays=computed(()=>{const rows=[];for(let d=start.value;d<=end.value;d=addDays(d,1)){const published=data.value.days.find((r:any)=>r.employee_id===auth.user?.id&&r.date===d);const draft=data.value.draft_days?.find((r:any)=>r.employee_id===auth.user?.id&&r.date===d);const rest=entitlement.value.planned_rest?.find((item:any)=>item.date===d);rows.push(published?{...published,rest_status:published.rest_status||rest?.status}:(draft?{...draft,status:draft.status||'pending_rule'}:{date:d,kind:'pending',label:labels.pending}))}return rows})
const weekScheduleRows=computed<any[]>(()=>[...(weekData.value.days||[]),...(weekData.value.draft_days||[]).map((row:any)=>({...row,status:row.status||'pending_rule'}))].sort((a:any,b:any)=>a.date.localeCompare(b.date)||a.employee_id-b.employee_id))
const loadedView=ref(false),selectionProjectId=ref(0)
const personPlan=ref<any>({employee_id:0,plan_id:null,template:'six_one',start_date:today,end_date:addDays(today,6),cycle_start:today,reason:'周期排班',days:[]})
const personPreview=ref<any>({rows:[],revision:''}),savedPersonPlans=ref<any[]>([]),bindableDays=ref<any[]>([]),selectedBindableDates=ref<string[]>([])
const personManualDates=new Set<string>()
const establishedCycleStart=ref<string|null>(null)
const personRows=computed<any[]>(()=>personPreview.value.rows.length?personPreview.value.rows:personPlan.value.days)
const canPreviewPerson=computed(()=>!!projectId.value && !!personPlan.value.employee_id && !personPlan.value.readonly && !!personPlan.value.start_date && !!personPlan.value.end_date && !!personPlan.value.cycle_start && personPlan.value.cycle_start<=personPlan.value.start_date && personPlan.value.start_date>=today && personPlan.value.end_date>=addDays(personPlan.value.start_date,patternLength(personPlan.value.template)-1) && dayDifference(personPlan.value.start_date,personPlan.value.end_date)<366 && !!String(personPlan.value.reason||'').trim())
const canConfirmPerson=computed(()=>canPreviewPerson.value && !!personPreview.value.revision && personPreview.value.rows.length>0)
function message(e:any){return typeof e.response?.data?.detail==='string'?e.response.data.detail:'操作失败，请核对日期和原因'}
async function loadEntitlement(){entitlementError.value='';try{entitlement.value=await get('/rotation/me/entitlement');entitlementLoaded.value=true}catch(e){entitlementLoaded.value=false;entitlementError.value=message(e)}}
function invalidatePersonPreview(){personPreview.value={rows:[],revision:''}}
function defaultDayKind(day:string){const length=patternLength(personPlan.value.template);const index=((dayDifference(personPlan.value.cycle_start,day)%length)+length)%length;return index<length-length/7?'work':'rest'}
function generatePersonDays(preserveManual=false){invalidatePersonPreview();const prior=new Map<string,any>(personPlan.value.days.map((row:any)=>[row.date,row]));const rows:any[]=[];if(!personPlan.value.start_date||!personPlan.value.end_date||personPlan.value.end_date<personPlan.value.start_date)return;for(let d=personPlan.value.start_date;d<=personPlan.value.end_date&&rows.length<366;d=addDays(d,1))rows.push(preserveManual&&personManualDates.has(d)&&prior.has(d)?{...prior.get(d)}:{date:d,kind:defaultDayKind(d),project_id:projectId.value,shift_label:null});personPlan.value.days=rows}
function newPersonPlan(){personManualDates.clear();const latest=savedPersonPlans.value.reduce((value:string,item:any)=>item.end_date>value?item.end_date:value,'');const startDay=[latest>=today?addDays(latest,1):today,String(selectedRule.value?.effective_date||'')].sort().pop()||today;personPlan.value={employee_id:personPlan.value.employee_id,plan_id:null,readonly:false,template:'six_one',start_date:startDay,end_date:addDays(startDay,6),cycle_start:establishedCycleStart.value||startDay,reason:'周期排班',days:[]};generatePersonDays()}
async function loadPersonPlans(){if(!projectId.value||!personPlan.value.employee_id){savedPersonPlans.value=[];bindableDays.value=[];return}const result:any=await get('/rotation/projects/'+projectId.value+'/person-plans/'+personPlan.value.employee_id);savedPersonPlans.value=Array.isArray(result.plans)?result.plans:[];bindableDays.value=Array.isArray(result.bindable_days)?result.bindable_days:[];establishedCycleStart.value=result.established_cycle_start||null;selectedBindableDates.value=[]}
async function personChanged(){savedPersonPlans.value=[];bindableDays.value=[];establishedCycleStart.value=null;if(personPlan.value.employee_id)await loadPersonPlans();newPersonPlan()}
function editSavedPlan(saved:any){personPlan.value={employee_id:personPlan.value.employee_id,plan_id:saved.id,readonly:saved.editable===false,template:saved.template,start_date:saved.start_date,end_date:saved.end_date,cycle_start:saved.cycle_start,reason:saved.reason||'周期排班',days:(saved.rows||[]).map((row:any)=>({date:row.date,kind:row.kind,project_id:row.project_id,shift_label:row.shift_label??null}))};personManualDates.clear();for(const row of personPlan.value.days)personManualDates.add(row.date);invalidatePersonPreview()}
function templateChanged(){personManualDates.clear();personPlan.value.end_date=addDays(personPlan.value.start_date,patternLength(personPlan.value.template)-1);generatePersonDays()}
function personStartChanged(){personManualDates.clear();personPlan.value.cycle_start=establishedCycleStart.value||personPlan.value.start_date;personPlan.value.end_date=addDays(personPlan.value.start_date,patternLength(personPlan.value.template)-1);generatePersonDays()}
function personRangeChanged(){generatePersonDays(true)}
function editPersonDay(date:string,field:'kind'|'project_id'|'shift_label',value:string){const row=personPlan.value.days.find((item:any)=>item.date===date);if(!row)return;row[field]=field==='project_id'?(value==='pending'?null:Number(value)):field==='shift_label'?(value||null):value;personManualDates.add(date);if(field==='kind'&&value==='rest')row.shift_label=null;invalidatePersonPreview()}
function personBody(){return {plan_id:personPlan.value.plan_id,start_date:personPlan.value.start_date,end_date:personPlan.value.end_date,cycle_start:personPlan.value.cycle_start,template:personPlan.value.template,days:personPlan.value.days.map((row:any)=>({date:row.date,kind:row.kind,project_id:row.project_id,shift_label:row.shift_label??null})),reason:personPlan.value.reason}}
async function previewPerson(){if(!canPreviewPerson.value)return;saving.value=true;error.value='';try{personPreview.value=await post('/rotation/projects/'+projectId.value+'/person-plans/'+personPlan.value.employee_id+'/preview',personBody())}catch(e){invalidatePersonPreview();error.value=message(e)}finally{saving.value=false}}
async function confirmPerson(){if(!canConfirmPerson.value)return;const dialog=await alertController.create({header:'确认个人排班',message:rotationRule.value?'属于本项目的未来日期将发布给员工；已发布日期须走调班审核。':'先保存此人计划；项目规则生效前不能打卡或攒休。',buttons:[{text:'返回',role:'cancel'},{text:'确认',handler:()=>{void doConfirmPerson()}}]});await dialog.present()}
async function doConfirmPerson(){saving.value=true;error.value='';try{await put('/rotation/projects/'+projectId.value+'/person-plans/'+personPlan.value.employee_id+'/confirm?revision='+encodeURIComponent(personPreview.value.revision),personBody());invalidatePersonPreview();await loadPersonPlans();await load();}catch(e){error.value=message(e)}finally{saving.value=false}}
async function bindSelectedDays(){if(!selectedBindableDates.value.length)return;const grouped=new Map<number,string[]>();for(const item of selectedBindableDates.value){const [id,date]=item.split('|');const planId=Number(id);if(!grouped.has(planId))grouped.set(planId,[]);grouped.get(planId)!.push(date)}saving.value=true;error.value='';try{for(const [planId,dates] of grouped)await post('/rotation/projects/'+projectId.value+'/person-plans/'+personPlan.value.employee_id+'/bind',{plan_id:planId,dates,reason:personPlan.value.reason||'项目交接后接入'});await loadPersonPlans();await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function load(){try{directory.value=await get('/field/directory');if(!loadedView.value){manageView.value=canViewProjectClaims.value&&(!canPunch.value||projectId.value>0);loadedView.value=true}else if(!canViewProjectClaims.value)manageView.value=false;data.value=await get('/rotation/calendar',{start:start.value,end:end.value,project_id:projectId.value||undefined,employee_id:manageView.value?undefined:auth.user?.id});if(canPunch.value)await loadEntitlement();if(manageView.value){weekData.value=await get('/rotation/calendar',{start:weekStart.value,end:weekEnd.value,project_id:projectId.value||undefined});if(projectId.value>0&&(selectionProjectId.value!==projectId.value||!personPlan.value.employee_id)){personPlan.value.employee_id=schedulableMembers.value[0]?.id||0;selectionProjectId.value=projectId.value;await personChanged()}}}catch(e){error.value=message(e)}}
function moveWeek(step:number){weekStart.value=addDays(weekStart.value,step*7);void load()}
function goThisWeek(){weekStart.value=monday(today);void load()}
function projectChanged(){selectionProjectId.value=0;personPlan.value.employee_id=0;void load()}
const adjustRow=ref<any>(null),adjustKind=ref('work'),adjustShiftLabel=ref(''),adjustReason=ref('')
function openAdjustment(row:any){adjustRow.value=row;adjustKind.value=row.kind==='work'?'rest':'work';adjustShiftLabel.value='';adjustReason.value=''}
async function submitAdjustment(){if(!adjustRow.value || !adjustReason.value.trim())return;saving.value=true;error.value='';try{const row=adjustRow.value;await post(`/rotation/projects/${row.project_id}/adjust`,{changes:[{employee_id:row.employee_id,date:row.date,kind:adjustKind.value,expected_revision:row.revision,...(adjustKind.value==='work' && adjustShiftLabel.value ? {shift_label:adjustShiftLabel.value==='none'?null:adjustShiftLabel.value} : {})}],reason:adjustReason.value.trim()});adjustRow.value=null;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
const form=ref({project_id:0,kind:'schedule',dayKind:'work',shiftLabel:'',start:today,end:today,reason:''})
async function submit(){if(!form.value.reason.trim()){error.value='请填写原因';return}if(form.value.end<form.value.start||form.value.end>addDays(form.value.start,61)){error.value='每次申请须为1至62天';return}saving.value=true;error.value='';try{const days=[];for(let d=form.value.start;d<=form.value.end;d=addDays(d,1))days.push({date:d,kind:form.value.dayKind,...(form.value.kind==='schedule' && form.value.dayKind==='work' && form.value.shiftLabel ? {shift_label:form.value.shiftLabel} : {})});await post('/rotation/claims',{project_id:form.value.project_id,kind:form.value.kind,days,reason:form.value.reason});form.value.reason='';await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
const reviewRow=ref<any>(null),reviewAction=ref('approve'),reviewDays=ref(0),reviewNote=ref('')
function openReview(row:any,action:string){reviewRow.value=row;reviewAction.value=action;reviewDays.value=row.current_facts?.suggested_days||0;reviewNote.value=''}
async function review(){if(!reviewNote.value.trim()){error.value='请填写审核原因';return}saving.value=true;try{await post(`/rotation/claims/${reviewRow.value.id}/review`,{action:reviewAction.value,note:reviewNote.value,...(reviewRow.value.kind==='credit'?{days:reviewDays.value}:{}),...(reviewRow.value.kind==='schedule' && reviewRow.value.status==='pending' && Number.isInteger(reviewRow.value.next_approval?.step_index)?{expected_step:reviewRow.value.next_approval.step_index}:{})});reviewRow.value=null;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
onIonViewWillEnter(()=>{const id=Number(route.query.project_id||0);if(id>0)projectId.value=id;loadedView.value=false;void load()})
</script>
<style scoped>
.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.day{border-radius:8px;min-height:69px;background:#f3f5f8;padding:6px 2px;text-align:center}.day small{display:block;font-size:10px;line-height:1.5}.work{background:#eaf5ff}.rest{background:#e7f5ee}.leave,.half_leave{background:#fff0d9}.today{outline:2px solid #397acf}.weekday{text-align:center;color:#63748a}.claim{padding:16px 0;border-bottom:1px solid #e5eaf0}.review{border:2px solid #397acf}.rotation-mobile h2{font-size:18px}
.draft,.rest-awaiting{background:#fff5df}.draft-status{color:#9a651c;font-weight:600}
.entitlement-card{border-color:#b7d8c1;background:#f5fbf6}.entitlement-amount strong{font-size:26px;color:#16844f}
.plan-people{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.plan-people label{display:inline-flex;gap:5px;align-items:center;padding:8px 10px;border:1px solid #dce4ee;border-radius:8px}.plan-preview{max-height:320px;overflow:auto;border-top:1px solid #e5eaf0;margin:14px 0}.plan-row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #e5eaf0}.plan-row small{color:#718096}.plan-row select{width:112px;flex:none}
.week-nav{flex-wrap:wrap;gap:8px;margin:14px 0}.week-nav button{border:1px solid #dce4ee;background:white;border-radius:8px;padding:8px 10px}
</style>
